      kg.gain.setValueAtTime(0.0001, at + d);
      kg.gain.exponentialRampToValueAtTime(a, at + d + 0.012);
      kg.gain.exponentialRampToValueAtTime(0.0001, at + d + 0.24);
      k.connect(kg).connect(g); k.start(at + d); k.stop(at + d + 0.27);
