  const bf = ctx.createBiquadFilter(); bf.type = 'lowpass'; bf.frequency.value = 150; bf.Q.value = 0.7;
  const bg = ctx.createGain(); bg.gain.value = 0.55;
  body.connect(bf).connect(bg).connect(out);
