  const crumble = noiseBurst(1.15, (x) => (Math.random() < 0.45 ? 0.2 + 0.8 * Math.random() : 0.12) * Math.pow(1 - x, 1.4));
  const cf = ctx.createBiquadFilter(); cf.type = 'lowpass'; cf.Q.value = 0.9;
