  const sg = ctx.createGain();
  sg.gain.setValueAtTime(0.0001, t + 0.3);
  sg.gain.exponentialRampToValueAtTime(0.05, t + 0.45);
  sg.gain.exponentialRampToValueAtTime(0.0001, t + 1.3);
  sift.connect(sf).connect(sg).connect(out);
