  if (inBunker) { sfxStepMetal(); setTimeout(sfxStepMetal, 95); } else if (inUndercroft) { sfxStepUnder(); setTimeout(sfxStepUnder, 95); } else { sfxStep(); setTimeout(sfxStep, 95); }
