/* AND THREE OF THEM ARE NOT WRITTEN AT ALL — THEY ARE SOMEBODY'S MOTION
 * CAPTURE, RETARGETED. `assets/ntar-moves.json` is three Mixamo clips put
 * through `tools/ntar_moves.py`: a compass kick, a side handspring and the
 * one where he is knocked onto his back. What the file carries is not a
 * pose and not a clip — it is, per bone per frame,
 *
 *     D = (that bone's world rotation) * (its world rotation at rest)^-1
 *
 * the rotation the bone has UNDERGONE. That is the one quantity that does
 * not care whose skeleton it came off: it knows nothing about Mixamo's bone
 * naming, nothing about which way Blender lays a bone's local axis, and
 * nothing about either rig's rest pose — so `ntarRetarget` can apply it to
 * the alien's own bind pose and get the same motion on a different body.
 * The map from one rig's bones to the other's is ALREADY IN THIS FILE:
 * `kind.rag` is written in the mutant's naming (`Character1_Hips`), which
 * is Mixamo's naming with a prefix, so the ragdoll's own table is the
 * retarget's table and there is no second list to keep in step.
 *
 * A hundred and sixteen kilobytes, and it may land after the creature is
 * dressed — so the clips it makes are added to `u.clips` whenever it
 * arrives, which costs nothing because `mutPlay` looks a clip up by name
 * on the frame it wants it. */
const NTAR_MOVES_URL = 'assets/ntar-moves.json';
let ntarMoves = null, ntarMovesLate = null;
/* THE KNIGHT'S SIX, the same way and off the same rig: a punch, a sweep, a
 * jump attack, a run and two guards. They are the owner's own pulls. */
const KNIGHT_MOVES_URL = 'assets/knight-moves.json';
let knightMoves = null, knightMovesLate = null;
bwFetch(KNIGHT_MOVES_URL, 647).then((buf) => {
  try { knightMoves = JSON.parse(new TextDecoder().decode(buf)); } catch (e) { return; }
  if (knightMovesLate) { knightMovesLate(); knightMovesLate = null; }
}, () => {});
bwFetch(NTAR_MOVES_URL, 1094).then((buf) => {
  try { ntarMoves = JSON.parse(new TextDecoder().decode(buf)); } catch (e) { return; }
  const K = ntarMoves.clips && ntarMoves.clips.knock;
  if (K) { NTAR_KNOCK.fall = K.dur; NTAR_KNOCK.land = K.land; }
  if (ntarMovesLate) { ntarMovesLate(); ntarMovesLate = null; }
}, () => {});
/* THE TWO RIGS' RESTS HAVE TO BE PUT ON TOP OF EACH OTHER FIRST. D is
 * measured from MIXAMO'S rest, which is an A-pose; this rig binds in a T.
 * Apply one to the other with no alignment and every limb sits forty-five
 * degrees off for the whole clip. So each bone is first turned by the
 * SMALLEST rotation that takes where it points its own child to where
 * Mixamo's rest points — the ragdoll's rule for driving one skeleton from
 * another, and the reason it is the smallest rotation and not a look-at is
 * the same: neither rig runs its bone axes along its bones. */
const NTAR_MX_CHILD = {
  Hips: 'Spine', Spine: 'Spine1', Spine1: 'Spine2', Spine2: 'Neck', Neck: 'Head',
  LeftShoulder: 'LeftArm', LeftArm: 'LeftForeArm', LeftForeArm: 'LeftHand',
  RightShoulder: 'RightArm', RightArm: 'RightForeArm', RightForeArm: 'RightHand',
  LeftUpLeg: 'LeftLeg', LeftLeg: 'LeftFoot', LeftFoot: 'LeftToeBase',
  RightUpLeg: 'RightLeg', RightLeg: 'RightFoot', RightFoot: 'RightToeBase',
};
function ntarRetarget(u, m, bones, bind, J, hipUp, hipPos, src) {
  /* AND IT DOES TWO CREATURES NOW. Nothing in here was ever about the alien:
   * what the file carries is the rotation a bone has UNDERGONE, and the map
   * from Mixamo's naming onto this rig's is `kind.rag`, which every creature
   * that can fall over already has. The knight's six moves come off the same
   * Mixamo rig and go onto an Unreal mannequin without a line of difference. */
  const data = src || ntarMoves;
  if (!data || !data.clips) return [];
  const rag = u.kind.rag || {};
  const mxOf = {};                                   // this rig's bone name -> Mixamo's
  for (const k in rag) if (k.startsWith('Character1_')) mxOf[rag[k]] = k.slice(11);

  /* THE BIND POSE, READ OFF THE RIG ITSELF. Every bone is put back to the
   * transform the file loaded with — the stance the other clips are built
   * on is NOT it, and using the stance would fold his arms-down pose into
   * every frame of somebody else's motion. Put back afterwards. */
  const held = new Map();
  for (const b of bones) held.set(b, { q: b.quaternion.clone(), p: b.position.clone() });
  for (const b of bones) { b.quaternion.copy(bind.get(b).q); b.position.copy(bind.get(b).p); }
  m.updateMatrixWorld(true);
  const mqi = m.getWorldQuaternion(new THREE.Quaternion()).invert();
  const mmi = m.matrixWorld.clone().invert();
  const mwp = m.getWorldPosition(new THREE.Vector3());
  const bW = new Map(), bP = new Map();
  for (const b of bones) {
    bW.set(b, b.getWorldQuaternion(new THREE.Quaternion()).premultiply(mqi));
    bP.set(b, b.getWorldPosition(new THREE.Vector3()).applyMatrix4(mmi));
  }
  // how far his own hips stand off the ground, against the hips in the file:
  // the lift and the fall are in metres and he is not the man they came off
  const hipWorld = J.hip ? J.hip.getWorldPosition(new THREE.Vector3()).y - mwp.y : 0;
  for (const b of bones) { b.quaternion.copy(held.get(b).q); b.position.copy(held.get(b).p); }
  m.updateMatrixWorld(true);

  const byName = {};
  for (const b of bones) byName[b.name] = b;
  const any = data.clips[Object.keys(data.clips)[0]];
  const RP = any.restPos;
  const hipK = (RP && RP.Hips && RP.Hips[1] > 0.05 && hipWorld > 0.05) ? hipWorld / RP.Hips[1] : 1;

  // the alignment, parents before children so a leaf can inherit one
  const _a = new THREE.Vector3(), _b2 = new THREE.Vector3();
  const A = new Map(), rootW = new Map();
  for (const b of bones) {
    const mx = mxOf[b.name];
    const pb = b.parent && b.parent.isBone ? b.parent : null;
    if (!pb) rootW.set(b, bW.get(b).clone().multiply(bind.get(b).q.clone().invert()));
    let q = pb ? (A.get(pb) || new THREE.Quaternion()) : new THREE.Quaternion();
    const kid = mx && NTAR_MX_CHILD[mx];
    const kb = kid && rag['Character1_' + kid] && byName[rag['Character1_' + kid]];
    if (mx && kb && RP[mx] && RP[kid]) {
      _a.subVectors(bP.get(kb), bP.get(b));
      _b2.set(RP[kid][0] - RP[mx][0], RP[kid][1] - RP[mx][1], RP[kid][2] - RP[mx][2]);
      if (_a.lengthSq() > 1e-8 && _b2.lengthSq() > 1e-8) {
        q = new THREE.Quaternion().setFromUnitVectors(_a.normalize(), _b2.normalize());
      }
    } else q = q.clone();
    A.set(b, q);
  }

  /* THE TWIST BONES, WHICH NOTHING HAS EVER DRIVEN — and they are most of
   * "some of his moves are awkward, his limbs should look natural when he
   * swings". An Unreal mannequin runs two twist joints down the middle of
   * every limb (`lowerarm_twist_01_r` and friends: sixteen of them on this
   * rig) and the skin along a forearm is weighted to THEM, not to the
   * forearm bone. The retarget maps what `kind.rag` names — the ragdoll's
   * twenty-two joints — so every twist bone fell through to the fallback
   * and simply inherited its parent. What that draws is the candy-wrapper:
   * the whole roll of a joint absorbed by one ring of vertices at the joint
   * itself, with the length of the limb dead. Measured on his own clips,
   * peak roll taken in a single step: 65 degrees at the wrist on the swipe,
   * 46 at the elbow on the spin, 28 at the ankle.
   *
   * A twist bone at a fraction f along its limb takes f of the DISTAL
   * joint's roll about that limb's own axis, so the skin ramps from nothing
   * at one end to the whole turn at the other instead of stepping. Nothing
   * is taken away from the joint itself, so the pose is untouched and only
   * the ramp between changes. The fractions are MEASURED off the rig rather
   * than assumed (they come out at clean thirds here, and 01 is the far end
   * on a forearm and the near end on an upper arm, which is exactly the
   * kind of thing not to hard-code). */
  const TWIST = [];
  for (const b of bones) {
    if (!/twist/i.test(b.name)) continue;
    const P = b.parent && b.parent.isBone ? b.parent : null;
    if (!P || !mxOf[P.name]) continue;
    const D = P.children.find((c) => c.isBone && mxOf[c.name]);   // the joint at the far end of this limb
    if (!D) continue;
    const L = D.position.length();
    if (L < 1e-6) continue;
    const f = Math.min(1, b.position.length() / L);
    if (f < 0.02) continue;
    TWIST.push({ b, D, f, axis: D.position.clone().normalize(), bq: bind.get(b).q });
  }
  /* The swing-twist split: the part of a rotation that is ABOUT the axis.
   * Project the quaternion's vector onto the axis and renormalise — the
   * remainder is the swing, which belongs to the joint and not to the
   * length of the limb. */
  const _tv = new THREE.Vector3(), _tp = new THREE.Vector3(), _tq = new THREE.Quaternion();
  const _bi = new THREE.Quaternion(), _id = new THREE.Quaternion();
  function twistAbout(q, axis, k, into) {
    _tv.set(q.x, q.y, q.z);
    _tp.copy(axis).multiplyScalar(_tv.dot(axis));
    _tq.set(_tp.x, _tp.y, _tp.z, q.w);
    if (_tq.lengthSq() < 1e-12) return into.identity();
    _tq.normalize();
    if (_tq.w < 0) { _tq.x = -_tq.x; _tq.y = -_tq.y; _tq.z = -_tq.z; _tq.w = -_tq.w; }
    return into.copy(_id).slerp(_tq, k);
  }

  const out = [];
  const _d = new THREE.Quaternion(), _w = new THREE.Quaternion(), _pi = new THREE.Quaternion();
  for (const name in data.clips) {
    const C = data.clips[name];
    const n = C.n, fps = data.fps || 30;
    const times = new Float32Array(n);
    for (let i = 0; i < n; i++) times[i] = i / fps;
    const vals = new Map();
    for (const b of bones) vals.set(b, new Float32Array(n * 4));
    const W = new Map();
    for (let i = 0; i < n; i++) {
      for (const b of bones) {                       // m.traverse order: parents first
        const pb = b.parent && b.parent.isBone ? b.parent : null;
        const pW = pb ? W.get(pb) : rootW.get(b);
        const mx = mxOf[b.name], tr = mx && C.d[mx];
        let w = W.get(b);
        if (!w) { w = new THREE.Quaternion(); W.set(b, w); }
        if (tr) {
          const o = i * 4;
          _d.set(tr[o], tr[o + 1], tr[o + 2], tr[o + 3]);
          w.copy(_d).multiply(A.get(b)).multiply(bW.get(b));
        } else {
          w.copy(pW).multiply(bind.get(b).q);
        }
        _pi.copy(pW).invert().multiply(w);
        const v = vals.get(b), o2 = i * 4;
        v[o2] = _pi.x; v[o2 + 1] = _pi.y; v[o2 + 2] = _pi.z; v[o2 + 3] = _pi.w;
      }
      /* and THEN the twists, because a twist bone reads the joint at the far
       * end of its own limb and that joint is a sibling — it may be written
       * before or after it depending on nothing but the order the file lists
       * them in. Both are local rotations in the same parent's frame, which
       * is the frame the limb's axis is measured in, so the share is simply
       * pre-multiplied onto the twist bone's own bind. */
      for (const t of TWIST) {
        const dv = vals.get(t.D), o = i * 4;
        _d.set(dv[o], dv[o + 1], dv[o + 2], dv[o + 3]);
        _bi.copy(bind.get(t.D).q).invert().multiply(_d);        // what the joint has DONE, not where it sits
        twistAbout(_bi, t.axis, t.f, _w);
        _pi.copy(_w).multiply(t.bq);
        const v = vals.get(t.b), o2 = i * 4;
        v[o2] = _pi.x; v[o2 + 1] = _pi.y; v[o2 + 2] = _pi.z; v[o2 + 3] = _pi.w;
      }
    }
    const tracks = [];
    for (const b of bones) tracks.push(new THREE.QuaternionKeyframeTrack(b.name + '.quaternion', times, vals.get(b)));
    /* AND THE HIPS RISE AND FALL. The uppercut takes him off the ground and
     * the flip puts his hands on it; without this he plays both standing
     * bolt upright on the spot. It is the leap's own track — the hips'
     * world up, in their parent's frame, per metre — with the two rigs'
     * hip heights divided out, and the HORIZONTAL travel deliberately left
     * out: root motion belongs to the game, which slides him itself. */
    if (J.hip && hipUp && C.hipY) {
      const pv = new Float32Array(n * 3);
      for (let i = 0; i < n; i++) {
        const dy = C.hipY[i] * hipK;
        pv[i * 3] = hipPos.x + hipUp.x * dy;
        pv[i * 3 + 1] = hipPos.y + hipUp.y * dy;
        pv[i * 3 + 2] = hipPos.z + hipUp.z * dy;
      }
      tracks.push(new THREE.VectorKeyframeTrack(J.hip.name + '.position', times, pv));
      /* AND THE GET-UP HAS TO STAY ON THE GROUND. The rise is this same reel
       * run BACKWARDS, which is the right shape — a fall reversed is a body
       * coming up off its back — except that reversing it also un-does the
       * punch, and he went two metres into the air: measured, his hips came
       * back up to 1.74 on the way to standing. So the knockdown keeps what
       * the clamp in `updateMutantUnit` needs — where the hips sit when he
       * is lying, and the line they may not rise above on the way up. */
      if (name === 'knock') u.ntarHip = { bone: J.hip, pos: hipPos.clone(), up: hipUp.clone(), lie: C.hipY[n - 1] * hipK };
    }
    /* AND HOW FAST THE CLIP ITSELF TRAVELS, so the game can play it at the
     * speed it is actually moving him. "The rate is the stride over the
     * speed" was set by hand for two clips; with a dozen gaits drawn against
     * each other it has to come off the data, or half of them skate. */
    if (C.travel && C.travel.length && C.dur > 0) {
      const T = C.travel[C.travel.length - 1];
      u.clipSpeed[name] = Math.hypot(T[0], T[1]) / C.dur;
      /* AND A ONE-OFF BEAT IS MOVED BY ITS OWN ROOT, NOT BY A NUMBER. The
       * horizontal travel is left out of the hips for a GAIT, because there
       * the game owns the speed — but a knockdown is a scripted beat where
       * the clip is the authority, and a fall slid along a hand-set vector
       * while the body goes somewhere else is the animation and the motion
       * disagreeing. The whole curve is kept so the knockdown can walk it. */
      u.clipTravel[name] = C.travel;
    }
    if (C.az) u.clipAz[name] = C.az;
    out.push(new THREE.AnimationClip(name, C.dur, tracks));
  }
  return out;
}

/* WRITING CLIPS ON A RIG NOBODY ANIMATED. Every clip is a list of KEYS —
 * a time and, per bone, an angle about the body's up, right and forward —
 * sampled at 30 fps and composed onto the STANCE (the demo clip's first
 * frame, with the arms brought to his sides the way the witness's are) as
 * turns in each bone's parent frame, which is exactly what `updateNtar`
 * does live. Every bone gets a track in every clip, driven or not, so a
 * crossfade between two of them can never let a bone fall back to the bind
 * pose — and this rig binds in a T. Sign conventions are the ones measured
 * on the witness: a thigh's `right` positive swings the foot BACK, a calf's
 * `right` positive folds it back, an arm's `right` negative brings it
 * FORWARD, an arm's `fwd` positive brings the right arm IN to the body (and
 * the left arm out). The contact pose of every swing is at the fraction
 * `MUT_ATTACKS` calls `hit`. */
const NTAR_JOINTS = {
  hip: 'CC_Base_Hip_02', waist: 'CC_Base_Waist_033', chest: 'CC_Base_Spine02_035',
  neck: 'CC_Base_NeckTwist01_036', head: 'CC_Base_Head_038',
  clavL: 'CC_Base_L_Clavicle_049', clavR: 'CC_Base_R_Clavicle_077',
  armL: 'CC_Base_L_Upperarm_050', armR: 'CC_Base_R_Upperarm_078',
  foreL: 'CC_Base_L_Forearm_051', foreR: 'CC_Base_R_Forearm_079',
  thighL: 'CC_Base_L_Thigh_04', thighR: 'CC_Base_R_Thigh_00',
  calfL: 'CC_Base_L_Calf_05', calfR: 'CC_Base_R_Calf_019',
  footL: 'CC_Base_L_Foot_06', footR: 'CC_Base_R_Foot_021',
};
// the arms brought to his sides: the witness's own numbers
const NTAR_HANG = { armR: { fwd: 0.33, right: -0.28 }, foreR: { fwd: 0.30, right: -0.12 }, armL: { fwd: -0.14 }, foreL: { fwd: -0.08 } };
/* ---------------------------------------------------------- writing a clip
 * A RIG THAT SHIPS NO FIGHT IS POSED IN CODE, and two creatures do it now —
 * the witness, whose file carries one demo clip, and the knight, whose file
 * carries six gaits and not one swing. What both need is the same three
 * things: the pose everything is built ON (a frame of a clip the file does
 * carry, because a rig's BIND pose is a T and nothing composed on a T looks
 * like a body), each driven joint's own parent frame expressed in the
 * BODY's axes (so a key can say "turn the shoulder about the body's right"
 * without knowing which way this rig lays its bone axes), and a builder that
 * eases a list of keys into a real `AnimationClip`.
 *
 * `JOINTS` maps this file's joint names onto the rig's bone names; `HANG` is
 * a fixed bias added to every key, which is how the witness's arms are
 * brought down to his sides. Returns the builder and the pieces a retarget
 * needs afterwards. */
function poseRig(u, m, src, JOINTS, HANG) {
  const bones = [];
  m.traverse((o) => { if (o.isBone) bones.push(o); });
  /* THE BIND POSE, BEFORE THE DEMO CLIP IS EVER PLAYED. The stance below is
   * the demo's first frame and it is what everything authored here is built
   * on; the RETARGET needs the pose the rig was bound in, which is a T, and
   * two lines from now the mixer will have stamped over it. */
  const bind = new Map();
  for (const b of bones) bind.set(b, { q: b.quaternion.clone(), p: b.position.clone() });
  const a = u.mixer.clipAction(src);
  a.play(); a.time = 0; u.mixer.update(0);
  m.updateMatrixWorld(true);
  const J = {};
  for (const k in JOINTS) J[k] = bones.find((b) => b.name === JOINTS[k]) || null;
  const base = new Map();
  for (const b of bones) base.set(b, b.quaternion.clone());
  const hipPos = J.hip ? J.hip.position.clone() : null;
  // the body's axes, in each driven bone's parent frame, at the stance
  const gq = new THREE.Quaternion(); m.getWorldQuaternion(gq);
  const W = { up: new THREE.Vector3(0, 1, 0), right: new THREE.Vector3(1, 0, 0).applyQuaternion(gq), fwd: new THREE.Vector3(0, 0, 1).applyQuaternion(gq) };
  const axes = {}, pq = new THREE.Quaternion();
  for (const k in J) {
    if (!J[k]) continue;
    (J[k].parent || J[k]).getWorldQuaternion(pq).invert();
    axes[k] = { up: W.up.clone().applyQuaternion(pq).normalize(), right: W.right.clone().applyQuaternion(pq).normalize(), fwd: W.fwd.clone().applyQuaternion(pq).normalize() };
  }
  // the hip's world up in its own parent's frame, per metre
  let hipUp = null;
  if (J.hip) {
    const ps = new THREE.Vector3(); (J.hip.parent || J.hip).getWorldScale(ps);
    hipUp = axes.hip.up.clone().divideScalar(Math.max(1e-6, ps.y));
  }
  a.stop();
  const tq = new THREE.Quaternion();
  const compose = (k, ang) => {
    const q = base.get(J[k]).clone();
    if (ang.up) q.premultiply(tq.setFromAxisAngle(axes[k].up, ang.up));
    if (ang.right) q.premultiply(tq.setFromAxisAngle(axes[k].right, ang.right));
    if (ang.fwd) q.premultiply(tq.setFromAxisAngle(axes[k].fwd, ang.fwd));
    return q;
  };
  const sm = (x) => x * x * (3 - 2 * x);
  /* one clip: keys are [t, {joint: {up, right, fwd}, hipY}] and every angle
   * is eased between the keys either side of the sample */
  const build = (name, dur, keys, loop) => {
    const fps = 30, n = Math.max(2, Math.round(dur * fps));
    const times = []; for (let i = 0; i <= n; i++) times.push((i / n) * dur);
    const at = (t, k, ax) => {
      let k0 = keys[0], k1 = keys[keys.length - 1];
      for (let i = 0; i < keys.length - 1; i++) if (t >= keys[i][0] && t <= keys[i + 1][0]) { k0 = keys[i]; k1 = keys[i + 1]; break; }
      const v0 = ax === 'hipY' ? (k0[1].hipY || 0) : ((k0[1][k] && k0[1][k][ax]) || 0);
      const v1 = ax === 'hipY' ? (k1[1].hipY || 0) : ((k1[1][k] && k1[1][k][ax]) || 0);
      const span = k1[0] - k0[0];
      const s = span > 1e-6 ? sm(THREE.MathUtils.clamp((t - k0[0]) / span, 0, 1)) : 1;
      return v0 + (v1 - v0) * s;
    };
    const tracks = [];
    for (const b of bones) {
      const k = Object.keys(J).find((kk) => J[kk] === b);
      const vals = [];
      for (let i = 0; i <= n; i++) {
        const t = times[i];
        let q;
        if (k) {
          const ang = { up: at(t, k, 'up'), right: at(t, k, 'right'), fwd: at(t, k, 'fwd') };
          if (HANG[k]) { ang.fwd += HANG[k].fwd || 0; ang.right += HANG[k].right || 0; }
          q = compose(k, ang);
        } else q = base.get(b);
        vals.push(q.x, q.y, q.z, q.w);
      }
      tracks.push(new THREE.QuaternionKeyframeTrack(b.name + '.quaternion', times, vals));
    }
    if (J.hip && hipUp) {
      const vals = [];
      for (let i = 0; i <= n; i++) { const dy = at(times[i], 'hip', 'hipY'); vals.push(hipPos.x + hipUp.x * dy, hipPos.y + hipUp.y * dy, hipPos.z + hipUp.z * dy); }
      tracks.push(new THREE.VectorKeyframeTrack(J.hip.name + '.position', times, vals));
    }
    return new THREE.AnimationClip(name, dur, tracks);
  };
  const stride = (A, C, arm, foreBend, lean, bob) => [
    [0,    { thighL: { right: -A }, calfL: { right: 0.15 }, thighR: { right: A }, calfR: { right: C }, armR: { right: -arm }, armL: { right: arm }, foreR: { right: -foreBend }, foreL: { right: -foreBend }, chest: { up: 0.08, right: lean }, head: { right: -lean * 0.6 }, hipY: -bob }],
    [0.25, { thighL: { right: -A * 0.2 }, calfL: { right: 0.05 }, thighR: { right: A * 0.1 }, calfR: { right: C * 1.4 }, armR: { right: -arm * 0.3 }, armL: { right: arm * 0.3 }, foreR: { right: -foreBend }, foreL: { right: -foreBend }, chest: { right: lean }, head: { right: -lean * 0.6 }, hipY: 0 }],
    [0.5,  { thighL: { right: A }, calfL: { right: C }, thighR: { right: -A }, calfR: { right: 0.15 }, armR: { right: arm }, armL: { right: -arm }, foreR: { right: -foreBend }, foreL: { right: -foreBend }, chest: { up: -0.08, right: lean }, head: { right: -lean * 0.6 }, hipY: -bob }],
    [0.75, { thighL: { right: A * 0.1 }, calfL: { right: C * 1.4 }, thighR: { right: -A * 0.2 }, calfR: { right: 0.05 }, armR: { right: arm * 0.3 }, armL: { right: -arm * 0.3 }, foreR: { right: -foreBend }, foreL: { right: -foreBend }, chest: { right: lean }, head: { right: -lean * 0.6 }, hipY: 0 }],
    [1.0,  { thighL: { right: -A }, calfL: { right: 0.15 }, thighR: { right: A }, calfR: { right: C }, armR: { right: -arm }, armL: { right: arm }, foreR: { right: -foreBend }, foreL: { right: -foreBend }, chest: { up: 0.08, right: lean }, head: { right: -lean * 0.6 }, hipY: -bob }],
  ];
  const scaleT = (keys, dur) => keys.map(([t, p]) => [t * dur, p]);
  return { bones, bind, J, base, hipPos, hipUp, build, compose, stride, scaleT };
}

