  const o = ctx.createOscillator();
  o.type = 'sine'; o.frequency.setValueAtTime(126, t); o.frequency.exponentialRampToValueAtTime(48, t + 0.22);
  o.connect(g); o.start(t); o.stop(t + 0.32);
